import{_ as l,o,c as t,aw as i}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Концепции","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/programming/fp/concept.md","filePath":"wiki/dev-commit/theory/programming/fp/concept.md"}'),s={name:"wiki/dev-commit/theory/programming/fp/concept.md"};function e(c,a,n,r,u,p){return o(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="концепции" tabindex="-1">Концепции <a class="header-anchor" href="#концепции" aria-label="Permalink to &quot;Концепции&quot;">​</a></h1><h3 id="чистые-функции-pure-functions" tabindex="-1">Чистые функции (Pure Functions) <a class="header-anchor" href="#чистые-функции-pure-functions" aria-label="Permalink to &quot;Чистые функции (Pure Functions)&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p></div><ul><li><strong>Чистые функции</strong></li><li>Возвращает один и тот же результат для одинаковых входных данных</li><li>Не изменяет входные данные (иммутабельность)</li><li>Не зависит от внешнего состояния (базы данных, DOM или глобальной переменной)</li><li>Не имеет побочных эффектов (side effects): не влияют на состояние программы</li><li>Чистые функции могут вызывать только чистые функции</li></ul><h4 id="условия" tabindex="-1">Условия <a class="header-anchor" href="#условия" aria-label="Permalink to &quot;Условия&quot;">​</a></h4><ul><li>Детерменированная - для одного и того же набора входных значений возвращает одинаковый результат</li><li>Без побочных эффектов В императивных языках некоторые функции в процессе выполнения своих вычислений могут модифицировать значения глобальных переменных, осуществлять операции ввода-вывода, реагировать на исключительные ситуации, вызывая их обработчики. Они называются функциями с побочными эффектами</li><li>Для замены циклов в JS можно использовать map и reduce</li></ul><h4 id="пример" tabindex="-1">Пример <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример&quot;">​</a></h4><ul><li>Функция, которая вызвала console.log() не является чистой</li><li>console.log() имеет Side effect, т.к. изменяет состояние консоли</li></ul><h3 id="функции-высшего-порядка-higher-order-functions" tabindex="-1">Функции высшего порядка (Higher Order Functions) <a class="header-anchor" href="#функции-высшего-порядка-higher-order-functions" aria-label="Permalink to &quot;Функции высшего порядка (Higher Order Functions)&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p></div><ul><li><strong>Функции высшего порядка</strong> - функция принимающая в качестве аргументов другие функции или возвращающая другую функцию в качестве результата</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">function</span><span style="color:#4078F2;"> higherOrderFunction</span><span style="color:#383A42;">(param, callback) {</span></span>
<span class="line"><span style="color:#A626A4;">  return</span><span style="color:#4078F2;"> callback</span><span style="color:#383A42;">(param);</span></span>
<span class="line"><span style="color:#383A42;">}</span></span></code></pre></div><h3 id="иммутабельность" tabindex="-1">Иммутабельность <a class="header-anchor" href="#иммутабельность" aria-label="Permalink to &quot;Иммутабельность&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p></div><ul><li><strong>Иммутабельность</strong> - свойство объектов не изменяться (н-р строка. строку нельзя поменять на месте, для изменения нужно создать новую строку). Применяется для списков, словарей и т.д. Иммутабельный список - список в который нельзя добавить / удалить элемент, можно только итерироваться по ним. Можно создать новый список который содежит все элементы +1, при этом старый остается валадным</li></ul><h3 id="каррирование-функции" tabindex="-1">Каррирование функций <a class="header-anchor" href="#каррирование-функции" aria-label="Permalink to &quot;Каррирование функций&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p></div><ul><li><strong>Каррирование функций</strong> - все функции могут быть от одного аргумента. Преобразование функции от пары аргументов в функцию, берущую свои аргументы по одному</li></ul><h3 id="функции-первого-класса" tabindex="-1">Функции первого класса <a class="header-anchor" href="#функции-первого-класса" aria-label="Permalink to &quot;Функции первого класса&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p></div><ul><li><strong>Функции первого класса</strong> - функция трактуются как объект, то есть может быть передана другим функциям и ее можно вернуть из функций. Так же ее можно присваивать переменным const foo = function() {}</li></ul><h3 id="рекурсия" tabindex="-1">Рекурсия <a class="header-anchor" href="#рекурсия" aria-label="Permalink to &quot;Рекурсия&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p></div><ul><li><strong>Рекурсия</strong> (рекурсивные функции) вызывают сами себя, позволяя операции выполняться снова и снова. В функциональных языках цикл обычно реализуется в виде рекурсии</li></ul><h3 id="лямбда-исчисление" tabindex="-1">Лямбда-исчисление <a class="header-anchor" href="#лямбда-исчисление" aria-label="Permalink to &quot;Лямбда-исчисление&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p></div><ul><li><strong>Лямбда-исчисление</strong> - механизм «анонимных функций» (Callback-функций), которые можно определить прямо в том месте, где они используются, и которые имеют доступ к локальным переменным текущей функции</li></ul>`,27)])])}const m=l(s,[["render",e]]);export{h as __pageData,m as default};
